from collections import defaultdict
from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Track used leave dates per employee to prevent duplicate counting
        # employee -> set of dates
        self._leave_taken: dict[str, set[date]] = defaultdict(set)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        # Requirement 2: End date before start date
        if end < start:
            raise ValueError("End date cannot be before start date.")

        # Requirement 3: Request made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Leave requests must be made at least 3 days in advance.")

        # Calculate applicable working days grouped by year
        days_by_year: dict[int, list[date]] = defaultdict(list)
        current = start
        while current <= end:
            # Weekdays only (Monday is 0, Sunday is 6) and exclude holidays
            if current.weekday() < 5 and current not in self.holidays:
                if current not in self._leave_taken[employee]:
                    days_by_year[current.year].append(current)
            current += timedelta(days=1)

        # Requirement 1: Verify sufficient remaining balance for all affected years
        for year, days in days_by_year.items():
            if len(days) > self.remaining(employee, year):
                raise ValueError(
                    f"Employee '{employee}' does not have enough remaining leave days for year {year}."
                )

        # Deduct leave days by recording them
        total_days = 0
        for days in days_by_year.values():
            self._leave_taken[employee].update(days)
            total_days += len(days)

        return total_days

    def remaining(self, employee: str, year: int) -> int:
        """Return the number of remaining leave days for an employee in a given year."""
        used = sum(1 for d in self._leave_taken[employee] if d.year == year)
        return max(0, self.days_per_year - used)
